const STORAGE_KEY = "sakthi_e_signatures_v2";

// Helper to generate SVG signature fallback if no custom upload exists
export function generateDefaultSignatureSvg(name: string): string {
  const initials = name
    .split(" ")
    .map((n) => n[0])
    .join("");
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="300" height="120" viewBox="0 0 300 120">
    <rect width="100%" height="100%" fill="#f8fafc"/>
    <path d="M 30 70 Q 70 20 120 70 T 210 50 T 270 80" stroke="#1e293b" stroke-width="3" fill="none" stroke-linecap="round"/>
    <text x="150" y="102" font-family="'Brush Script MT', cursive, sans-serif" font-size="24" font-style="italic" fill="#0f172a" text-anchor="middle">${name}</text>
    <text x="280" y="112" font-family="monospace" font-size="9" fill="#64748b" text-anchor="end">e-Signed [${initials}]</text>
  </svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

// Load signatures from LocalStorage or default registry
export function getRegisteredSignatures(): ElectronicSignature[] {
  if (typeof window === "undefined") return INITIAL_MEMBERS;
  const stored = localStorage.getItem(STORAGE_KEY);
  if (!stored) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(INITIAL_MEMBERS));
    return INITIAL_MEMBERS;
  }
  try {
    const parsed = JSON.parse(stored);
    if (Array.isArray(parsed) && parsed.length > 0) {
      return parsed;
    }
  } catch {}
  return INITIAL_MEMBERS;
}

// Fetch signatures from PostgreSQL / Supabase with local fallback
export async function fetchSignaturesFromSupabase(): Promise<ElectronicSignature[]> {
  try {
    const { data, error } = await supabase
      .from("employee_signatures")
      .select("*")
      .order("employee_number", { ascending: true });

    if (!error && data && data.length > 0) {
      const mapped: ElectronicSignature[] = data.map((item: any) => ({
        id: item.id,
        employee_number: item.employee_number,
        unique_member_id: item.unique_member_id || `SAK-EMP-${item.employee_number}`,
        employee_name: item.employee_name,
        designation: item.designation,
        department: item.department,
        signature_url: item.signature_url || generateDefaultSignatureSvg(item.employee_name),
        updated_at: item.updated_at || new Date().toISOString(),
        is_verified: item.is_verified ?? true,
      }));

      if (typeof window !== "undefined") {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(mapped));
        window.dispatchEvent(new Event("sakthi_signatures_updated"));
      }
      return mapped;
    }
  } catch (err) {
    console.warn("PostgreSQL signature fetch notice:", err);
  }
  return getRegisteredSignatures();
}

// Save signature image for a member to both PostgreSQL (Supabase) & Local Storage
export async function saveEmployeeSignatureToSupabase(
  employeeNumber: string,
  signatureUrl: string,
  uniqueMemberId?: string
): Promise<boolean> {
  const current = getRegisteredSignatures();
  const member = current.find((m) => m.employee_number === employeeNumber);

  if (member) {
    member.signature_url = signatureUrl;
    member.updated_at = new Date().toISOString();
    member.is_verified = true;
    if (uniqueMemberId) member.unique_member_id = uniqueMemberId;

    if (typeof window !== "undefined") {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(current));
      window.dispatchEvent(new Event("sakthi_signatures_updated"));
    }

    try {
      await supabase.from("employee_signatures").upsert({
        employee_number: member.employee_number,
        unique_member_id: member.unique_member_id || `SAK-EMP-${member.employee_number}`,
        employee_name: member.employee_name,
        designation: member.designation,
        department: member.department,
        signature_url: signatureUrl,
        is_verified: true,
        updated_at: member.updated_at,
      }, { onConflict: "employee_number" });
    } catch (err) {
      console.warn("PostgreSQL upsert fallback notice:", err);
    }
    return true;
  }
  return false;
}

// Synchronous save for legacy components
export function saveEmployeeSignature(employeeNumber: string, signatureUrl: string): boolean {
  saveEmployeeSignatureToSupabase(employeeNumber, signatureUrl);
  return true;
}

// Authenticate employee number and get electronic signature
export function authenticateAndGetSignature(employeeNumber: string): ElectronicSignature | null {
  const list = getRegisteredSignatures();
  const found = list.find((m) => m.employee_number.trim() === employeeNumber.trim());
  if (found) {
    if (!found.signature_url) {
      found.signature_url = generateDefaultSignatureSvg(found.employee_name);
    }
    return found;
  }
  return null;
}
